let method = $json.method;
if (!method) {
  method = $json.headers?.[':method'] || 'POST';
}
return [{ json: { ...$json, method: method } }];

// ── Node: Code — Parse & Validate Form Body ──────────────────

const body = $json.body;

// Guard: reject missing or empty body immediately
if (!body || typeof body !== 'object') {
  throw new Error('400: Request body is missing or not an object');
}

// Guard: required fields
const required = ['departure', 'destination', 'startDate', 'endDate'];
const missing = required.filter(k => !body[k] || String(body[k]).trim() === '');
if (missing.length > 0) {
  throw new Error(`400: Missing required fields: ${missing.join(', ')}`);
}

// Date sanity check
const start = new Date(body.startDate);
const end   = new Date(body.endDate);
if (isNaN(start.getTime()) || isNaN(end.getTime())) {
  throw new Error('400: startDate or endDate is not a valid date');
}
if (end < start) {
  throw new Error('400: endDate must be on or after startDate');
}

// Safe array helper for multi-select fields
const safeArray = (val) =>
  Array.isArray(val) ? val : (val ? [val] : []);

return [{ json: {
  departure:         body.departure.trim(),
  destination:       body.destination.trim(),
  startDate:         body.startDate.trim(),
  endDate:           body.endDate.trim(),
  tripType:          body.tripType          || 'Not specified',
  dayActivity:       safeArray(body.dayActivity),
  nightActivity:     safeArray(body.nightActivity),
  groupSize:         body.groupSize          || '1',
  ageRange:          safeArray(body.ageRange),
  budget:            body.budget             || '0',
  email:             (body.email || '').trim(),
  accommodationType: body.accommodationType  || '',
  amenities:         safeArray(body.amenities),
  starRating:        body.starRating         || '',
  flightPreference:  body.flightPreference   || '',
  transferNeeds:     body.transferNeeds      || '',
}}];

// ── Node: Prepare Tropical Data — Build AI prompt ────────────

const {
  departure, destination, startDate, endDate,
  tripType, dayActivity, nightActivity,
  groupSize, ageRange, budget, email,
  accommodationType, amenities, starRating,
  flightPreference, transferNeeds
} = $json;

const fmt = (val) =>
  Array.isArray(val) && val.length > 0 ? val.join(', ') : 'No preference';

// User message only — formatting rules live in the system prompt
const prompt = `Please create a complete tropical trip itinerary with the following details:

- Departure: ${departure}
- Destination: ${destination}
- Dates: ${startDate} to ${endDate}
- Trip Type: ${tripType}
- Group Size: ${groupSize}
- Age Ranges: ${fmt(ageRange)}
- Budget: $${budget} USD total
- Day Activities: ${fmt(dayActivity)}
- Night Activities: ${fmt(nightActivity)}
- Accommodation Type: ${accommodationType || 'No preference'}
- Resort Amenities: ${fmt(amenities)}
- Star Rating: ${starRating || 'No preference'}
- Flight Preference: ${flightPreference || 'No preference'}
- Airport Transfer: ${transferNeeds || 'No preference'}

Please follow the formatting rules in the system prompt exactly.`;

return [{ json: {
  departure, destination, startDate, endDate,
  tripType, dayActivity, nightActivity,
  groupSize, ageRange, budget, email,
  accommodationType, amenities, starRating,
  flightPreference, transferNeeds,
  prompt
}}];

// ── Node: Format Daily Schedule — Parse & render AI output ───

// STEP 1: Safe extraction with full validation
const rawContent = $node['OpenAI'].json?.message?.content;

if (!rawContent || rawContent.trim() === '') {
  const finishReason = $node['OpenAI'].json?.message?.finish_reason || 'unknown';
  throw new Error(
    `OpenAI returned empty content. Finish reason: ${finishReason}. ` +
    'Check your API quota, content policy, or prompt length.'
  );
}

// STEP 2: Sanitise — strip accidental Markdown code fences
const itineraryRaw = rawContent
  .replace(/```[\w]*\n?/g, '')
  .replace(/```/g, '')
  .trim();

// STEP 3: Parse line by line
const itineraryLines = itineraryRaw.split('\n');
let formattedItinerary = '';
let inDailySchedule = false;
let inCostSummary   = false;
let scheduleLines   = [];
let costSummaryRows = [];

const formatDailySchedule = (lines) => {
  let output = '<strong style="font-size:16px;color:#2a4a6e;display:block;margin:15px 0 5px 0;">Daily Schedule:</strong>';
  const joined = lines.join(' ');
  const daySections = joined.match(/(Day \d+:.*?)(?=(Day \d+:|$))/g);
  if (!daySections) return output + '<br>';
  daySections.forEach((dayMatch, index) => {
    const dayLabelMatch = dayMatch.match(/(Day \d+:[^\-]*)/);
    if (!dayLabelMatch) return;
    const dayLabel = dayLabelMatch[1].trim();
    const subItems = dayMatch.match(/- (Morning|Afternoon|Evening):.*?(?=(Day \d+:|- (Morning|Afternoon|Evening):|$))/g);
    output += `<strong>${dayLabel}</strong>`;
    if (subItems) {
      const content = subItems.map(i => i.trim()).join('<br>');
      output += `<div style="margin:4px 0 8px 12px;">${content}</div>`;
    }
    if (index < daySections.length - 1) output += '<br>';
  });
  return output + '<br>';
};

for (let line of itineraryLines) {
  line = line.trim();

  if (!line) {
    if (inDailySchedule) {
      formattedItinerary += formatDailySchedule(scheduleLines);
      inDailySchedule = false;
      scheduleLines = [];
    } else if (inCostSummary) {
      inCostSummary = false;
      formattedItinerary += `<table style="border-collapse:collapse;width:100%;margin:10px 0;font-size:14px;">${costSummaryRows.join('')}</table><br>`;
      costSummaryRows = [];
    } else {
      formattedItinerary += '<br>';
    }
    continue;
  }

  const lower = line.toLowerCase();

  if (lower.startsWith('daily schedule:')) {
    inDailySchedule = true;
    scheduleLines = [];
    continue;
  }

  if (inDailySchedule) {
    scheduleLines.push(line);
    continue;
  }

  if (lower.startsWith('cost summary:')) {
    formattedItinerary += `<strong style="font-size:16px;color:#2a4a6e;display:block;margin:15px 0 5px 0;">Cost Summary:</strong>`;
    inCostSummary = true;
    continue;
  }

  if (inCostSummary && line.includes('\t')) {
    const parts = line.split('\t').map(s => s.trim());
    const category = parts[0] || '';
    const cost     = parts[1] || '';
    const isBold   = category.startsWith('Total') || category.startsWith('Remaining Budget');
    const cellStyle = isBold
      ? 'border:1px solid #e0e0e0;padding:8px;background:#f0f0f0;font-weight:bold;'
      : 'border:1px solid #e0e0e0;padding:8px;';
    costSummaryRows.push(`<tr><td style="${cellStyle}">${category}</td><td style="${cellStyle}">${cost}</td></tr>`);
    continue;
  }

  if (inCostSummary) {
    inCostSummary = false;
    formattedItinerary += `<table style="border-collapse:collapse;width:100%;margin:10px 0;font-size:14px;">${costSummaryRows.join('')}</table><br>`;
    costSummaryRows = [];
  }

  if (line.endsWith(':')) {
    formattedItinerary += `<strong style="font-size:16px;color:#2a4a6e;display:block;margin:15px 0 5px 0;">${line}</strong>`;
  } else {
    formattedItinerary += `${line}<br>`;
  }
}

// Final flush
if (inDailySchedule && scheduleLines.length > 0) {
  formattedItinerary += formatDailySchedule(scheduleLines);
}
if (costSummaryRows.length > 0) {
  formattedItinerary += `<table style="border-collapse:collapse;width:100%;margin:10px 0;font-size:14px;">${costSummaryRows.join('')}</table><br>`;
}

return [{ json: { ...$json, itinerary: formattedItinerary } }];

// ── Node: Trip Info — Merge AI output with form data ─────────

const trip = $node['Prepare Tropical Data'].json;
const ai   = $node['Format Daily Schedule'].json;

if (!trip || !ai) {
  throw new Error('Trip Info: missing data from upstream nodes. Check Prepare Tropical Data and Format Daily Schedule.');
}

if (!ai.itinerary || ai.itinerary.trim() === '') {
  throw new Error('Trip Info: itinerary is empty after formatting.');
}

return [{ json: {
  destination:       trip.destination,
  startDate:         trip.startDate,
  endDate:           trip.endDate,
  tripType:          trip.tripType,
  dayActivity:       trip.dayActivity,
  nightActivity:     trip.nightActivity,
  groupSize:         trip.groupSize,
  ageRange:          trip.ageRange,
  budget:            trip.budget,
  email:             trip.email,
  departure:         trip.departure,
  accommodationType: trip.accommodationType,
  amenities:         trip.amenities,
  starRating:        trip.starRating,
  itinerary:         ai.itinerary
}}];

// ── Node: Resolve Email Content — Build HTML email & session ──

const destination  = $json.destination  || 'Your Destination';
const departure    = $json.departure    || 'Not specified';
const travelDates  = `${$json.startDate || 'N/A'} to ${$json.endDate || 'N/A'}`;
const budget       = $json.budget       || 'N/A';
const groupSize    = $json.groupSize    || 'N/A';
const tripType     = $json.tripType     || 'N/A';
const dayActivity  = Array.isArray($json.dayActivity)  ? $json.dayActivity.join(', ')  : ($json.dayActivity  || 'Not specified');
const nightActivity= Array.isArray($json.nightActivity)? $json.nightActivity.join(', '): ($json.nightActivity|| 'Not specified');
const ageRange     = Array.isArray($json.ageRange)     ? $json.ageRange.join(', ')     : ($json.ageRange     || 'Not specified');
const itinerary    = $json.itinerary    || 'Itinerary details not available.';

const subject = `Your Tropical Itinerary for ${destination} – Voyage Genie`;

const message = `
<div style="padding:5px;background-color:#ffffff;border-radius:10px 10px 0 0;">
  <h2 style="color:#2a4a6e;font-size:22px;margin:0 0 15px 0;">Departing from: ${departure}</h2>
  <h2 style="color:#2a4a6e;font-size:22px;margin:0 0 15px 0;">Destination: ${destination}</h2>
  <p style="color:#333;font-size:16px;margin:10px 0;line-height:1.5;"><strong>Travel Dates:</strong> ${travelDates}</p>
  <p style="color:#333;font-size:16px;margin:10px 0;line-height:1.5;"><strong>Trip Type:</strong> ${tripType}</p>
  <p style="color:#333;font-size:16px;margin:10px 0;line-height:1.5;"><strong>Day Activities:</strong> ${dayActivity}</p>
  <p style="color:#333;font-size:16px;margin:10px 0;line-height:1.5;"><strong>Night Activities:</strong> ${nightActivity}</p>
  <p style="color:#333;font-size:16px;margin:10px 0;line-height:1.5;"><strong>Age Range:</strong> ${ageRange}</p>
  <p style="color:#333;font-size:16px;margin:10px 0;line-height:1.5;"><strong>Budget:</strong> $${budget} (for ${groupSize} travelers)</p>
  <hr style="border:0;border-top:1px solid #e0e0e0;margin:25px 0;">
  <h3 style="color:#2a4a6e;font-size:18px;margin:0 0 15px 0;">Itinerary Details</h3>
  <div style="background:#f9f9f9;padding:10px;border-radius:10px;font-size:14px;line-height:1.6;color:#333;">
    ${itinerary}
  </div>
  <hr style="border:0;border-top:1px solid #e0e0e0;margin:25px 0;">
  <p style="color:#666;font-size:12px;text-align:center;margin:0;">Generated by <strong>Voyage Genie</strong> 🌟</p>
</div>`;

// Collision-resistant session ID
const sessionId = [
  Date.now().toString(36),
  Math.random().toString(36).slice(2, 7)
].join('-');

return [{ json: {
  sessionId,
  itineraryHtml:   message,
  resolvedEmail:   ($json.email || '').trim(),
  resolvedSubject: subject,
  resolvedMessage: message,
  formData: {
    departure,
    destination,
    startDate:  $json.startDate,
    endDate:    $json.endDate,
    budget,
    groupSize,
    tripType
  }
}}];

// ── Node: Trigger Email Workflow — Retry-safe email dispatch ──

const EMAIL_WEBHOOK = 'https://exodonprofits.app.n8n.cloud/webhook/send-email';
const MAX_RETRIES   = 2;
const RETRY_DELAY   = 1500;

const payload = {
  resolvedEmail:   $json.resolvedEmail,
  resolvedSubject: $json.resolvedSubject,
  resolvedMessage: $json.resolvedMessage,
};

// Skip silently if no email address was provided
if (!payload.resolvedEmail || payload.resolvedEmail === '') {
  return $input.all();
}

const sleep = (ms) => new Promise(r => setTimeout(r, ms));

let lastError;
for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
  try {
    await $http({
      method:  'POST',
      url:     EMAIL_WEBHOOK,
      body:    payload,
      headers: { 'Content-Type': 'application/json' },
    });
    return $input.all();
  } catch (err) {
    lastError = err;
    if (attempt < MAX_RETRIES) await sleep(RETRY_DELAY);
  }
}

// All retries exhausted — log and continue (email is non-critical)
console.error(`Email delivery failed after ${MAX_RETRIES} attempts: ${lastError?.message}`);
return $input.all();

return [{ json: {
  sessionId:     $json.sessionId,
  redirectUrl:   $json.redirectUrl,
  itineraryData: $json.itineraryData,
  itineraryHtml: $json.itineraryHtml
}}];

// ── Node: Retrieve Itinerary — Return 404 (not yet persisted) ─
// Phase 3: replace this with a Supabase SELECT by sessionId
const sessionId = $json.query?.sessionId || 'unknown';
return [{ json: {
  error: 'Itinerary persistence not yet implemented.',
  hint:  'Connect this node to Supabase to fetch by sessionId.',
  sessionId
}}];

let method = $json.method;
if (!method) {
  method = $json.headers?.[':method'] || 'POST';
}
return [{ json: { ...$json, method: method } }];

// ── Node: Prepare New Suggestion — Alternative destination AI call

const body = $json.body || $json;

const destination = body.destination || 'unknown';
const budget      = body.budget      || '0';
const tripType    = body.tripType    || 'Not specified';
const startDate   = body.startDate   || '';
const endDate     = body.endDate     || '';

const prompt = `The user is currently planning a trip to ${destination} with a budget of $${budget} for a ${tripType} trip${startDate ? ` from ${startDate} to ${endDate}` : ''}.

Suggest 3 alternative tropical destinations that:
- Have similar weather and beach quality
- Fit within the same budget range
- Suit a ${tripType} traveler

For each destination provide:
- Destination name and country
- Why it is a great alternative
- Estimated total cost (flights + 7 nights accommodation)
- Best time to visit
- One standout experience unique to that destination
- A booking link or search link (e.g. Skyscanner or Booking.com)

Format each suggestion clearly with a heading and bullet points.`;

return [{ json: { ...body, prompt } }];

// ── Node: Format New Suggestion Response ──────────────────────

const rawContent = $node['OpenAI New Suggestion'].json?.message?.content;

if (!rawContent || rawContent.trim() === '') {
  throw new Error('OpenAI New Suggestion returned empty content.');
}

const sessionId = [
  Date.now().toString(36),
  Math.random().toString(36).slice(2, 7)
].join('-');

return [{ json: {
  sessionId,
  suggestions: rawContent.trim(),
  suggestionsHtml: rawContent.trim().replace(/\n/g, '<br>')
}}];
